<?php
include('../auth/check.php');
include('../config/db.php');

$queue_id = intval($_GET['queue_id'] ?? 0);
if ($queue_id <= 0) { header('Location: assessment_screen.php'); exit; }

$stmt = $conn->prepare("SELECT q.id AS queue_id,q.queue_number,q.queue_type,q.workflow_status,q.beneficiary_id,b.beneficiary_code,b.first_name,b.middle_name,b.last_name,b.ext_name,b.contact_number,b.birthday_month,b.birthday_day,b.birthday_year,b.age,b.sex,b.region,b.province,b.city_municipality,b.barangay,b.lgu,b.national_id,b.household_id,b.program_type,b.sms_opt_in,b.is_pregnant FROM queue_entries q INNER JOIN beneficiaries b ON b.id=q.beneficiary_id WHERE q.id=? LIMIT 1");
$stmt->bind_param('i',$queue_id);
$stmt->execute();
$data = $stmt->get_result()->fetch_assoc();
if (!$data) { header('Location: assessment_screen.php'); exit; }

$stmt = $conn->prepare("SELECT * FROM eligibility_forms WHERE queue_entry_id=? OR beneficiary_id=? ORDER BY id DESC LIMIT 1");
$stmt->bind_param('ii',$queue_id,$data['beneficiary_id']);
$stmt->execute();
$form = $stmt->get_result()->fetch_assoc() ?: [];
$charter = [];
if (!empty($form['remarks'])) {
    $tmp = json_decode($form['remarks'], true);
    if (is_array($tmp)) $charter = $tmp;
}

function h($v){return htmlspecialchars($v ?? '',ENT_QUOTES,'UTF-8');}
function s($f,$k,$v){return (strval($f[$k] ?? '')===strval($v))?'selected':'';}
function c($arr,$k,$v){return in_array($v, $arr[$k] ?? [], true)?'checked':'';}
function cv($arr,$k,$default=''){return htmlspecialchars($arr[$k] ?? $default,ENT_QUOTES,'UTF-8');}
function selc($arr,$k,$v){return (($arr[$k] ?? '')===$v)?'selected':'';}
$is_locked = intval($form['form_locked'] ?? 0) === 1;
$name = trim($data['last_name'].', '.$data['first_name'].' '.$data['middle_name'].' '.$data['ext_name']);
$birthday = intval($data['birthday_month']).'/'.intval($data['birthday_day']).'/'.intval($data['birthday_year']);
$isPwd = intval($data['sms_opt_in'] ?? 0) === 1;
$isPregnant = intval($data['is_pregnant'] ?? 0) === 1;
$isSenior = intval($data['age'] ?? 0) >= 60;
$priorityText = $isPwd ? 'PWD Priority' : ($isPregnant ? 'Pregnant Priority' : ($isSenior ? 'Senior Citizen Priority' : 'Regular'));
$completeAddress = trim(($data['barangay'] ?? '').', '.($data['city_municipality'] ?? '').', '.($data['province'] ?? '').', '.($data['region'] ?? ''), ', ');
$program = $data['program_type'] ?: 'Cash Relief Assistance';
$requirements = [
    'Common Requirements' => ['One (1) valid ID of client/person to be interviewed','Barangay Certification in lieu of ID, if extremely justifiable','Signed Authorization Letter, if applicable'],
    'Transportation Assistance' => ['Police Blotter','Medical Abstract','Court Order or Subpoena','Death Certificate'],
    'Medical Assistance - Hospital Bill' => ['Medical Certificate / Clinical Abstract / Discharge Summary / Alagang Pinoy Tagubilin Form issued within three (3) months','Hospital Bill / Statement of Account / Certificate of Balance / Promissory Note','Social Case Study Report or Case Summary'],
    'Medical Assistance - Medicine / Assistive Device' => ['Medical Certificate / Clinical Abstract / Discharge Summary / Alagang Pinoy Tagubilin Form issued within three (3) months','Prescription issued within three (3) months','Quotation if assistance requested exceeds Php10,000.00','Social Case Study Report or Case Summary if assistance exceeds Php10,000.00'],
    'Medical Assistance - Laboratory' => ['Medical Certificate / Clinical Abstract / Discharge Summary / Alagang Pinoy Tagubilin Form issued within three (3) months','Laboratory Request / Laboratory Protocol / Doctor\'s Order','Quotation if assistance requested exceeds Php10,000.00','Social Case Study Report or Case Summary'],
    'Funeral Assistance' => ['Death Certificate or Certification from Tribal Chieftain / Imam','Promissory Note / Certificate of Balance / Statement of Account','Funeral Contract','Transfer Permit, if transfer of cadaver'],
    'Educational Assistance' => ['Validated School ID and valid ID','Enrollment Assessment Form / Certificate of Enrollment or Registration / Statement of Account'],
    'Food Assistance' => ['Barangay Certificate of Residency / Indigency / Certificate that client is in need of assistance','Medical document proving beneficiary is admitted, if applicable'],
    'Cash Relief Assistance' => ['Fire victims: Police Report or Bureau of Fire Protection Report','Distressed OFs: Passport / Travel Documents / OWWA or Barangay Certification','Rescued client: Social Worker or Case Manager Certification','Online sexual exploitation victims: Police Blotter and Social Worker Certification','LSI without valid ID: Medical Certificate or Travel Authority issued by PNP','Other incidents: Barangay Certificate / Police Report / Blotter / Spot Report / JAPIC / DAFAC / Medico-legal certification'],
    'Material Assistance' => ['General Intake Sheet','Material Assistance Distribution Sheet']
];
?>
<!DOCTYPE html><html><head><meta charset="UTF-8"><title>AICS GIS / CE Form</title><link href="https://fonts.googleapis.com/icon?family=Material+Icons" rel="stylesheet"><link rel="stylesheet" href="../assets/style.css"><style>
