ine{display:grid;grid-template-columns:110px 1.4fr 1.6fr 120px;gap:0;border-bottom:1px solid #e5e7eb}.rowline:last-child{border-bottom:0}.rowline>div{padding:10px;border-right:1px solid #e5e7eb}.rowline>div:last-child{border-right:0}.head{background:#dbeafe;font-weight:1000;color:#111827}.hidden-by-mode{display:none}@media(max-width:1000px){.grid,.info,.checkgrid{grid-template-columns:1fr}.wide,.half{grid-column:span 1}.rowline{grid-template-columns:1fr}.rowline>div{border-right:0;border-bottom:1px solid #e5e7eb}.rowline>div:last-child{border-bottom:0}}
</style></head><body><div class="app"><main class="main"><section class="wrap">
<div class="card"><h1>AICS General Intake Sheet (GIS) / Certificate of Eligibility (CE)</h1><p class="muted">Aligned with DSWD AICS Citizen's Charter for onsite individual clients and offsite/group clients.</p><div class="lock <?php echo $is_locked?'locked':'draft'; ?>"><?php echo $is_locked?'Approved and Locked':'Draft / Not yet approved'; ?></div>
<div class="info"><div><span>Queue</span><strong><?php echo h($data['queue_number']); ?></strong></div><div><span>Beneficiary Code</span><strong><?php echo h($data['beneficiary_code']); ?></strong></div><div class="wide"><span>Client Name</span><strong><?php echo h($name); ?></strong></div><div><span>Birthday</span><strong><?php echo h($birthday); ?></strong></div><div><span>Age / Sex</span><strong><?php echo intval($data['age']); ?> / <?php echo h($data['sex']); ?></strong></div><div><span>Contact Number</span><strong><?php echo h($data['contact_number'] ?: '-'); ?></strong></div><div class="<?php echo ($isPwd||$isPregnant||$isSenior)?'priority':''; ?>"><span>Priority Status</span><strong><?php echo h($priorityText); ?></strong></div><div><span>Program / Assistance</span><strong><?php echo h($program); ?></strong></div><div><span>Region</span><strong><?php echo h($data['region']); ?></strong></div><div><span>Province</span><strong><?php echo h($data['province']); ?></strong></div><div><span>City / Municipality</span><strong><?php echo h($data['city_municipality']); ?></strong></div><div class="wide"><span>Complete Address</span><strong><?php echo h($completeAddress); ?></strong></div></div></div>
<form class="card" method="POST" action="../api/save_eligibility.php">
<input type="hidden" name="queue_id" value="<?php echo intval($queue_id); ?>"><input type="hidden" name="beneficiary_id" value="<?php echo intval($data['beneficiary_id']); ?>">
<h2 class="section-title">I. Transaction Classification</h2><div class="grid"><div class="field"><label>Citizen Charter Mode</label><select name="charter[transaction_mode]" id="mode" <?php echo $is_locked?'disabled':''; ?>><option value="Onsite Individual" <?php echo selc($charter,'transaction_mode','Onsite Individual'); ?>>Onsite Individual - CIU/CIS/SWAD Office</option><option value="Offsite Group" <?php echo selc($charter,'transaction_mode','Offsite Group'); ?>>Offsite / Group of Individuals</option></select></div><div class="field"><label>Classification</label><input name="charter[classification]" value="<?php echo cv($charter,'classification','Simple'); ?>" <?php echo $is_locked?'disabled':''; ?>></div><div class="field"><label>Type of Transaction</label><input name="charter[transaction_type]" value="<?php echo cv($charter,'transaction_type','G2C - Government to Citizen'); ?>" <?php echo $is_locked?'disabled':''; ?>></div><div class="field full"><label>Who May Avail</label><textarea name="charter[who_may_avail]" <?php echo $is_locked?'disabled':''; ?>><?php echo cv($charter,'who_may_avail','Indigent, marginalized, vulnerable/disadvantaged individuals and families or otherwise in crisis situation based on the assessment of the Social Worker.'); ?></textarea></div></div>
<h2 class="section-title">II. Client Identifying Information - GIS</h2><div class="grid"><div class="field"><label>ID Presented / Barangay Certification</label><select name="id_type_presented" <?php echo $is_locked?'disabled':''; ?> required><option value="">Select</option><option value="PhilSys ID" <?php echo s($form,'id_type_presented','PhilSys ID'); ?>>PhilSys ID</option><option value="UMID / SSS / GSIS ID" <?php echo s($form,'id_type_presented','UMID / SSS / GSIS ID'); ?>>UMID / SSS / GSIS ID</option><option value="PhilHealth ID" <?php echo s($form,'id_type_presented','PhilHealth ID'); ?>>PhilHealth ID</option><option value="Driver's License" <?php echo s($form,'id_type_presented',"Driver's License"); ?>>Driver's License</option><option value="PRC ID" <?php echo s($form,'id_type_presented','PRC ID'); ?>>PRC ID</option><option value="Voter's ID / Certification" <?php echo s($form,'id_type_presented',"Voter's ID / Certification"); ?>>Voter's ID / Certification</option><option value="Passport" <?php echo s($form,'id_type_presented','Passport'); ?>>Passport</option><option value="4Ps ID" <?php echo s($form,'id_type_presented','4Ps ID'); ?>>4Ps ID</option><option value="PWD ID" <?php echo s($form,'id_type_presented','PWD ID'); ?>>PWD ID</option><option value="Solo Parent ID" <?php echo s($form,'id_type_presented','Solo Parent ID'); ?>>Solo Parent ID</option><option value="OSCA ID" <?php echo s($form,'id_type_presented','OSCA ID'); ?>>OSCA ID</option><option value="Barangay Certification" <?php echo s($form,'id_type_presented','Barangay Certification'); ?>>Barangay Certification in lieu of ID</option><option value="Other Valid ID" <?php echo s($form,'id_type_presented','Other Valid ID'); ?>>Other Valid ID</option></select></div><div class="field"><label>ID Number / Remarks</label><input name="id_reference_note" value="<?php echo h($form['id_reference_note'] ?? $data['national_id'] ?? ''); ?>" <?php echo $is_locked?'disabled':''; ?>></div><div class="field"><label>Authorization Letter</label><select name="charter[authorization_letter]" <?php echo $is_locked?'disabled':''; ?>><option value="Not Applicable" <?php echo selc($charter,'authorization_letter','Not Applicable'); ?>>Not Applicable</option><option value="Presented" <?php echo selc($charter,'authorization_letter','Presented'); ?>>Presented</option><option value="Required but Missing" <?php echo selc($charter,'authorization_letter','Required but Missing'); ?>>Required but Missing</option></select></div><div class="field"><label>Household Members</label><input type="number" min="1" name="household_members" value="<?php echo h($form['household_members'] ?? ''); ?>" <?php echo $is_locked?'disabled':''; ?>></div><div class="field"><label>Dependents</label><input type="number" min="0" name="dependents" value="<?php echo h($form['dependents'] ?? ''); ?>" <?php echo $is_locked?'disabled':''; ?>></div><div class="field"><label>Monthly Income</label><input type="number" min="0" step="0.01" name="monthly_income" value="<?php echo h($form['monthly_income'] ?? '0'); ?>" <?php echo $is_locked?'disabled':''; ?>></div><div class="field"><label>Source of Income</label><input name="income_source" value="<?php echo h($form['income_source'] ?? ''); ?>" placeholder="Salary, business, none, etc." <?php echo $is_locked?'disabled':''; ?>></div><div class="field"><label>Client Category</label><input name="beneficiary_type" value="<?php echo h($form['beneficiary_type'] ?? $priorityText); ?>" <?php echo $is_locked?'disabled':''; ?>></div><div class="field"><label>Assistance Requested</label><input name="assistance_reason" value="<?php echo h($form['assistance_reason'] ?? $program); ?>" <?php echo $is_locked?'disabled':''; ?>></div></div>
<h2 class="section-title">III. Checklist of Requirements Presented</h2><p class="mini">Check documents actually presented. If incomplete, issue compliance instruction before approval.</p><?php foreach($requirements as $group=>$items): ?><div class="card" style="padding:14px;background:#fbfdff"><b><?php echo h($group); ?></b><div class="checkgrid" style="margin-top:10px"><?php foreach($items as $item): ?><label class="check"><input type="checkbox" name="charter[requirements][]" value="<?php echo h($group.' - '.$item); ?>" <?php echo c($charter,'requirements',$group.' - '.$item); ?> <?php echo $is_locked?'disabled':''; ?>> <span><?php echo h($item); ?></span></label><?php endforeach; ?></div></div><?php endforeach; ?>
<h2 class="section-title">IV. Onsite / Offsite Citizen Charter Steps</h2><div class="tablebox"><div class="rowline head"><div>Step</div><div>Client Step</div><div>Agency Action to Record</div><div>Status</div></div><div class="rowline onsite"><div>Step 1</div><div>Secure queue number and present pertinent documents.</div><div>Provide queue number, check validity/completeness of documents, and verify client records/frequency in CrIMS or existing monitoring system.</div><div><select name="charter[onsite_step1]" <?php echo $is_locked?'disabled':''; ?>><option <?php echo selc($charter,'onsite_step1','Done'); ?>>Done</option><option <?php echo selc($charter,'onsite_step1','Pending'); ?>>Pending</option><option <?php echo selc($charter,'onsite_step1','Not Applicable'); ?>>Not Applicable</option></select></div></div><div class="rowline onsite"><div>Step 2</div><div>Submit documents for interview and assessment.</div><div>SWO interviews and assesses client, verifies authenticity, fills out GIS and CE, determines eligibility, and recommends appropriate assistance.</div><div><select name="charter[onsite_step2]" <?php echo $is_locked?'disabled':''; ?>><option <?php echo selc($charter,'onsite_step2','Done'); ?>>Done</option><option <?php echo selc($charter,'onsite_step2','Pending'); ?>>Pending</option><option <?php echo selc($charter,'onsite_step2','Not Applicable'); ?>>Not Applicable</option></select></div></div><div class="rowline onsite"><div>Step 3</div><div>Receive assistance / wait for release.</div><div>Forward documents to authorized official, approve valid/complete requests, prepare GL if applicable, confirm identity, and release assistance.</div><div><select name="charter[onsite_step3]" <?php echo $is_locked?'disabled':''; ?>><option <?php echo selc($charter,'onsite_step3','Done'); ?>>Done</option><option <?php echo selc($charter,'onsite_step3','Pending'); ?>>Pending</option><option <?php echo selc($charter,'onsite_step3','Not Applicable'); ?>>Not Applicable</option></select></div></div><div class="rowline onsite"><div>Step 4</div><div>Fill out Client Satisfaction Measurement Survey.</div><div>Issue/receive CSMF and file/scan documents for records.</div><div><select name="charter[onsite_step4]" <?php echo $is_locked?'disabled':''; ?>><option <?php echo selc($charter,'onsite_step4','Pending'); ?>>Pending</option><option <?php echo selc($charter,'onsite_step4','Done'); ?>>Done</option><option <?php echo selc($charter,'onsite_step4','Not Applicable'); ?>>Not Applicable</option></select></div></div><div class="rowline offsite"><div>Pre-Offsite</div><div>Submit project proposal and beneficiary list.</div><div>Receive, assess, review, approve project proposal, cross-match beneficiary list, and inform group of payout schedule and requirements.</div><div><select name="charter[offsite_prep]" <?php echo $is_locked?'disabled':''; ?>><option <?php echo selc($charter,'offsite_prep','Not Applicable'); ?>>Not Applicable</option><option <?php echo selc($charter,'offsite_prep','Done'); ?>>Done</option><option <?php echo selc($charter,'offsite_prep','Pending'); ?>>Pending</option></select></div></div><div class="rowline offsite"><div>Offsite Step 1</div><div>Present pertinent documents.</div><div>Assigned personnel checks validity/completeness. If missing, SWO advises compliance before next step.</div><div><select name="charter[offsite_step1]" <?php echo $is_locked?'disabled':''; ?>><option <?php echo selc($charter,'offsite_step1','Not Applicable'); ?>>Not Applicable</option><option <?php echo selc($charter,'offsite_step1','Done'); ?>>Done</option><option <?php echo selc($charter,'offsite_step1','Pending'); ?>>Pending</option></select></div></div><div class="rowline offsite"><div>Offsite Step 2</div><div>Submit documents for interview and assessment.</div><div>SWO fills identifying information in GIS, conducts interview/assessment, establishes eligibility, and completes GIS and CE.</div><div><select name="charter[offsite_step2]" <?php echo $is_locked?'disabled':''; ?>><option <?php echo selc($charter,'offsite_step2','Not Applicable'); ?>>Not Applicable</option><option <?php echo selc($charter,'offsite_step2','Done'); ?>>Done</option><option <?php echo selc($charter,'offsite_step2','Pending'); ?>>Pending</option></select></div></div><div class="rowline offsite"><div>Offsite Step 3</div><div>Receive assistance.</div><div>Check client's identity and release assistance.</div><div><select name="charter[offsite_step3]" <?php echo $is_locked?'disabled':''; ?>><option <?php echo selc($charter,'offsite_step3','Not Applicable'); ?>>Not Applicable</option><option <?php echo selc($charter,'offsite_step3','Done'); ?>>Done</option><option <?php echo selc($charter,'offsite_step3','Pending'); ?>>Pending</option></select></div></div></div>
<h2 class="section-title">V. SWO Assessment and Certificate of Eligibility</h2><div class="grid"><div class="field"><label>CrIMS / Frequency Check</label><select name="matches_masterlist" <?php echo $is_locked?'disabled':''; ?> required><option value="Yes" <?php echo s($form,'matches_masterlist','Yes'); ?>>Eligible based on frequency / no disqualifying record</option><option value="No" <?php echo s($form,'matches_masterlist','No'); ?>>Not eligible or frequency issue found</option></select></div><div class="field"><label>Document Status</label><select name="supporting_documents" <?php echo $is_locked?'disabled':''; ?> required><option value="Complete and Valid" <?php echo s($form,'supporting_documents','Complete and Valid'); ?>>Complete and Valid</option><option value="Incomplete - Compliance Slip Issued" <?php echo s($form,'supporting_documents','Incomplete - Compliance Slip Issued'); ?>>Incomplete - Compliance Slip Issued</option><option value="For Verification" <?php echo s($form,'supporting_documents','For Verification'); ?>>For Verification</option></select></div><div class="field"><label>Eligibility Status</label><select name="eligibility_status" <?php echo $is_locked?'disabled':''; ?> required><option value="Pending Review" <?php echo s($form,'eligibility_status','Pending Review'); ?>>Pending Review</option><option value="Eligible" <?php echo s($form,'eligibility_status','Eligible'); ?>>Eligible</option><option value="Not Eligible" <?php echo s($form,'eligibility_status','Not Eligible'); ?>>Not Eligible / Disapproved</option></select></div><div class="field"><label>Assistance Mode</label><select name="charter[assistance_mode]" <?php echo $is_locked?'disabled':''; ?>><option value="Cash Outright" <?php echo selc($charter,'assistance_mode','Cash Outright'); ?>>Cash Outright</option><option value="Guarantee Letter" <?php echo selc($charter,'assistance_mode','Guarantee Letter'); ?>>Guarantee Letter</option><option value="Material Assistance" <?php echo selc($charter,'assistance_mode','Material Assistance'); ?>>Material Assistance</option><option value="Referral" <?php echo selc($charter,'assistance_mode','Referral'); ?>>Referral</option><option value="Disapproval Letter" <?php echo selc($charter,'assistance_mode','Disapproval Letter'); ?>>Disapproval Letter</option></select></div><div class="field"><label>Recommended / Approved Amount</label><input type="number" min="0" step="0.01" name="approved_cash_amount" value="<?php echo h($form['approved_cash_amount'] ?? '0'); ?>" <?php echo $is_locked?'disabled':''; ?>></div><div class="field"><label>Already Received Assistance?</label><select name="already_received_payout" <?php echo $is_locked?'disabled':''; ?>><option value="No" <?php echo s($form,'already_received_payout','No'); ?>>No</option><option value="Yes" <?php echo s($form,'already_received_payout','Yes'); ?>>Yes</option></select></div><div class="field"><label>Receiving Other Assistance?</label><select name="receiving_other_assistance" <?php echo $is_locked?'disabled':''; ?>><option value="No" <?php echo s($form,'receiving_other_assistance','No'); ?>>No</option><option value="Yes" <?php echo s($form,'receiving_other_assistance','Yes'); ?>>Yes</option></select></div><div class="field full"><label>Social Worker Assessment / Justification / Reason for Ineligibility</label><textarea name="charter[swo_assessment]" <?php echo $is_locked?'disabled':''; ?>><?php echo cv($charter,'swo_assessment'); ?></textarea></div><div class="field full"><label>Remarks for GIS / CE / GL / Compliance Slip / Referral</label><textarea name="charter[ce_remarks]" <?php echo $is_locked?'disabled':''; ?>><?php echo cv($charter,'ce_remarks'); ?></textarea></div></div>
<div class="actions"><?php if(!$is_locked): ?><button class="btn save" type="submit" name="action" value="save">Save Draft</button><button class="btn approve" type="submit" name="action" value="approve">Approve / Lock GIS & CE</button><?php endif; ?><a class="btn back" href="assessment_screen.php">Back</a></div></form></section></main><?php include('sidebar.php'); ?></div><script>function modeToggle(){let m=document.getElementById('mode').value;document.querySelectorAll('.onsite').forEach(x=>x.style.display=m==='Offsite Group'?'none':'grid');document.querySelectorAll('.offsite').forEach(x=>x.style.display=m==='Offsite Group'?'grid':'none')}document.getElementById('mode').addEventListener('change',modeToggle);modeToggle();</script></body></html>
